(async()=>{
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 13.5 6.8 4m0-11-6.8 4"/>',folder:'<path d="M20 20H4a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h5l2 2h9a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2Z"/>',chevron:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V3H3v13h5"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H5l-3 2 2-6v-4.5a8.5 8.5 0 0 1 17 0Z"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',send:'<path d="m22 2-7 20-4-9L2 9 22 2Zm-11 11L22 2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]}</svg>`;
const templates=await (await fetch('templates.json')).json();const main=$('.ws-main');
const tableParser=document.createElement('div');tableParser.innerHTML=templates.agents;const originalTable=tableParser.querySelector('.ws-agents-table').outerHTML;
const chatParser=document.createElement('div');chatParser.innerHTML=templates.chat;const userTemplate=chatParser.querySelector('.ws-chat-message.user').outerHTML,agentTemplate=chatParser.querySelector('.ws-chat-message.agent').outerHTML;
const members=[{name:'林悦',email:'linyue@example.com',role:'execute',status:'accepted'},{name:'沈宁',email:'shenning@example.com',role:'view',status:'pending'}];
const agentMembers=[{name:'周明',email:'zhouming@example.com',role:'execute',status:'accepted'}];
const incoming=[{id:'s1',project:'Steer',owner:'林悦',title:'检查会话重连的异常路径',role:'execute',status:'accepted'},{id:'s2',project:'Steer',owner:'林悦',title:'补充弱网场景的测试',role:'view',status:'pending'},{id:'s3',project:'Relay',owner:'周明',title:'检查 Node 重连与任务恢复',role:'view',status:'accepted'},{id:'s4',project:'Steer',owner:'周明',title:'整理项目 Runtime 配置',role:'execute',status:'accepted'}];
const agents=[{id:'builder',name:'Builder',role:'开发与实现',runtime:'dev-machine / Codex',model:'gpt-6.1-sol',owner:'Alex'},{id:'reviewer',name:'Reviewer',role:'代码审查',runtime:'dev-machine / TraeX',model:'gpt-5.6-sol',owner:'Alex'}];
const provided=[{id:'writer',name:'Writer',role:'文案与说明 · 林悦共享 · Steer',runtime:'lin-mac / Codex',model:'gpt-6.1-sol',owner:'林悦',status:'accepted'},{id:'review',name:'Reviewer',role:'代码审查 · 周明共享 · Relay',runtime:'dev-server / TraeX',model:'gpt-5.6-sol',owner:'周明',status:'pending'}];
const state={view:'chat',tab:'mine',session:null,working:false};
const dialog=document.createElement('dialog');dialog.id='ref-dialog';document.body.append(dialog);
const toast=document.createElement('div');toast.className='ref-toast';toast.hidden=true;document.body.append(toast);let toastTimer;
function tell(text){toast.textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,2400)}
function modal(title,subtitle,body){dialog.innerHTML=`<header><h2>${title}</h2><button type="button" data-ref="close-dialog" aria-label="关闭弹窗">${icon('close')}</button></header>${subtitle?`<p class="ref-dialog-context" title="${esc(subtitle)}">${esc(subtitle)}</p>`:''}${body}`;dialog.showModal()}
function renderInvite(kind='session',agent){
state.dialogKind=kind;state.popupAgent=agent;const currentMembers=kind==='agent'?agentMembers:members;
const label=kind==='agent'?agent.name:'登录重连与异常处理';
const caption=kind==='agent'?`${agent.runtime} · 授权项目 Steer`:'Steer · '+label;
modal(kind==='agent'?'共享智能体':'邀请协作',caption,`${kind==='agent'?'<div class="ref-scope-line">执行范围：Steer 项目 · 独立 Git worktree</div>':''}<form class="ref-invite-form" data-kind="${kind}"><label>邮箱<input type="email" name="email" placeholder="colleague@example.com" required autocomplete="off"></label><label>权限<select name="role">${kind==='agent'?'<option value="execute">可使用</option>':'<option value="execute">可协作</option><option value="view">可查看</option>'}</select></label><button type="submit" class="ref-primary">邀请</button></form><p class="ref-permission-note">${kind==='agent'?'接收者可以在授权项目中创建自己的私密会话。':'可协作的成员可以在此会话发起 Agent 任务。'}</p><div class="ref-member-heading"><span>协作者</span><small>${currentMembers.length+1} 人</small></div><div class="ref-members"><div class="ref-member"><span class="ref-avatar">A</span><div><strong>Alex <small>你</small></strong><span>alex@example.com</span></div><span class="ref-owner-label">所有者</span></div>${currentMembers.map((m,i)=>`<div class="ref-member"><span class="ref-avatar ${m.status==='pending'?'pending':''}">${esc(m.name[0])}</span><div><strong>${esc(m.name)} ${m.status==='pending'?'<small>待接受</small>':''}</strong><span>${esc(m.email)}</span></div><select aria-label="${esc(m.name)}的权限" data-member-role="${i}"><option value="execute" ${m.role==='execute'?'selected':''}>可协作</option><option value="view" ${m.role==='view'?'selected':''}>可查看</option></select><button type="button" class="ref-icon" data-ref="remove-member" data-index="${i}" aria-label="移除 ${esc(m.name)}" title="移除协作者">${icon('close')}</button></div>`).join('')}</div><p class="ref-dialog-footnote">${kind==='agent'?'仅开放此智能体的授权执行范围，个人工作区保持私有。':'仅开放此会话，个人工作区保持私有。'}</p>`);
if(kind==='agent')dialog.querySelectorAll('[data-member-role]').forEach(select=>{select.innerHTML='<option value="execute">可使用</option>';select.disabled=true});
}
function avatarStack(){return members.length?`<button type="button" class="ref-avatar-stack" data-ref="invite" aria-label="查看协作者" title="${esc(members.map(m=>m.name+' · '+(m.status==='pending'?'待接受':m.role==='execute'?'可协作':'可查看')).join('\n'))}"><span class="ref-avatar owner">A</span>${members.slice(0,2).map(m=>`<span class="ref-avatar ${m.status==='pending'?'pending':''}">${esc(m.name[0])}</span>`).join('')}${members.length>2?`<span class="ref-avatar">+${members.length-2}</span>`:''}</button>`:''}
function renderChat(session){state.view='chat';state.session=session||null;main.innerHTML=templates.chat;main.querySelectorAll('script').forEach(n=>n.remove());const appbar=main.querySelector('.ws-chat-appbar'),context=appbar.querySelector('.ws-chat-appbar-context');
const share=appbar.querySelector('.ws-chat-share-trigger');share.removeAttribute('disabled');share.innerHTML=icon('share');share.title='分享查看链接';share.setAttribute('aria-label','分享查看链接');share.dataset.ref='public-link';
if(session){context.querySelector('strong').textContent=session.title;context.querySelector('span').innerHTML=`${icon('folder')}<small>${esc(session.owner)} 的 ${esc(session.project)} · ${session.role==='execute'?'可协作':'可查看'}</small>`;share.insertAdjacentHTML('beforebegin',`<button type="button" class="ref-icon ref-invite-trigger" data-ref="access" aria-label="会话访问权限" title="会话访问权限">${icon('users')}</button>`);const reply=main.querySelector('.ws-markdown');reply.innerHTML='<p>已完成初步检查，可以继续补充这项任务的要求。</p>';main.querySelector('.ws-chat-message.user p').textContent='请检查当前项目，整理需要处理的问题。';}
else {share.insertAdjacentHTML('beforebegin',`${avatarStack()}<button type="button" class="ref-icon ref-invite-trigger" data-ref="invite" aria-label="邀请协作" title="邀请协作">${icon('users')}</button>`)}
const editor=main.querySelector('.ws-inline-editor'),send=main.querySelector('.ws-chat-send');const readOnly=session?.role==='view';editor.contentEditable=String(!readOnly);editor.dataset.placeholder=readOnly?'此会话仅授予查看权限':'提出问题或描述一项任务…';send.disabled=Boolean(readOnly)||!editor.textContent.trim();editor.addEventListener('input',()=>send.disabled=Boolean(readOnly)||!editor.textContent.trim());send.dataset.ref='send';main.querySelector('.ws-chatbox').addEventListener('submit',e=>{e.preventDefault();sendDemo()});editor.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendDemo()}});
appbar.querySelector('[aria-label="切换侧栏"],[aria-label="Toggle sidebar"]')?.addEventListener('click',()=>document.body.classList.toggle('ref-nav-open'));updateSidebarState();
}
function sendDemo(){if(state.working||state.session?.role==='view')return;const editor=main.querySelector('.ws-inline-editor'),text=editor.textContent.trim();if(!text)return;const container=main.querySelector('.ws-chat-thread');const u=document.createElement('div');u.innerHTML=userTemplate;u.querySelector('p').textContent=text;u.querySelectorAll('.ws-user-message-actions').forEach(n=>n.remove());container.append(u.firstElementChild);const a=document.createElement('div');a.innerHTML=agentTemplate;a.querySelector('.ws-markdown').innerHTML='<p>这是一条本地演示回复：已收到你的要求。</p>';container.append(a.firstElementChild);editor.textContent='';main.querySelector('.ws-chat-send').disabled=true;const area=main.querySelector('.ws-chat-center');area.scrollTop=area.scrollHeight;}
function renderAgents(tab='mine'){state.view='agents';state.tab=tab;state.session=null;main.innerHTML=templates.agents;const page=main.querySelector('.ws-page');const tabs=page.querySelector('.ws-system-tabs');tabs.innerHTML=`<button type="button" class="ref-tab" data-ref="agent-tab" data-tab="mine" aria-pressed="${tab==='mine'}">我的智能体 · 2</button><button type="button" class="ref-tab" data-ref="agent-tab" data-tab="received" aria-pressed="${tab==='received'}">共享给我 · 2</button>`;page.querySelector('.ws-agents-table')?.remove();page.querySelectorAll('.ws-sharing-page,.ws-form-error').forEach(n=>n.remove());const tableWrap=document.createElement('div');tableWrap.innerHTML=originalTable;const table=tableWrap.firstElementChild;const rowTemplate=table.querySelector('div:not(.ws-table-head)').cloneNode(true);table.querySelectorAll(':scope>div:not(.ws-table-head)').forEach(n=>n.remove());
(tab==='mine'?agents:provided).forEach(a=>{const row=rowTemplate.cloneNode(true),spans=[...row.children];spans[0].textContent=a.name[0];spans[1].innerHTML=`<strong>${esc(a.name)}</strong><small>${esc(a.role)}${tab==='mine'&&a.id==='builder'?' · 已共享':''}</small>`;spans[2].textContent=a.runtime;spans[3].textContent=a.model;spans[4].innerHTML=`<i class="${a.status==='pending'?'ref-pending-dot':''}"></i>${a.status==='pending'?'待接受':'可使用'}`;spans[5].innerHTML=tab==='mine'?`<button type="button" data-ref="agent-share" data-agent="${a.id}" aria-label="共享 ${a.name}" title="共享能力">${icon('users')}</button><button type="button" data-ref="agent-use" data-agent="${a.id}" aria-label="使用 ${a.name}" title="开始聊天">${icon('chat')}</button>`:`<button type="button" data-ref="agent-detail" data-agent="${a.id}" aria-label="查看 ${a.name} 的能力" title="查看能力">${icon('eye')}</button><button type="button" data-ref="agent-detail" data-agent="${a.id}" aria-label="${a.status==='pending'?'接受并使用':'使用'} ${a.name}" title="${a.status==='pending'?'接受并使用':'开始聊天'}">${icon('chat')}</button>`;table.append(row)});page.append(table);if(tab==='received'){const note=page.querySelector('.ws-system-note');if(note)note.innerHTML=icon('users')+'智能体由提供者授权；使用时会在你的工作区创建私密会话。'}main.querySelector('.ws-topbar span')&&(main.querySelector('.ws-topbar span').textContent='智能体');updateSidebarState();}
function groupedSessions(sidebar=false){const groups=[...new Set(incoming.map(s=>s.owner+'/'+s.project))];return groups.map((key,i)=>{const list=incoming.filter(s=>s.owner+'/'+s.project===key),first=list[0];return `<details class="ref-project-group ${sidebar?'sidebar-group':''}" ${!sidebar||i===0?'open':''}><summary>${icon('chevron')}${icon('folder')}<strong>${esc(first.project)}</strong><span>${esc(first.owner)}</span>${!sidebar?`<small>${list.length} 个会话</small>`:''}</summary><div class="ref-project-sessions">${list.map(s=>`<button type="button" data-ref="open-incoming" data-session="${s.id}" class="ref-session-row ${state.session?.id===s.id?'active':''}"><span>${esc(s.title)}</span>${s.status==='pending'?'<small class="ref-invited">待接受</small>':!sidebar?`<small>${s.role==='execute'?'可协作':'可查看'}</small>`:''}</button>`).join('')}</div></details>`}).join('')}
function renderCollaboration(){state.view='collaboration';state.session=null;main.innerHTML=`<header class="ws-topbar"><button type="button" class="ref-icon ref-mobile-toggle" data-ref="toggle-sidebar" aria-label="切换侧栏">${icon('folder')}</button><span>协作会话</span></header><div class="ws-page ref-collaboration-page"><div class="ref-page-intro"><h1>协作会话</h1><p>别人与你共享的会话，按项目组织。</p></div><label class="ref-project-search"><input aria-label="搜索协作会话" placeholder="搜索项目、会话或提供者…"></label><div class="ref-project-list">${groupedSessions()}</div><p class="ref-page-note">你共享的会话仍在自己的项目下，顶部协作者头像可查看和管理成员。</p></div>`;main.querySelector('input').addEventListener('input',e=>{const term=e.target.value.toLowerCase();main.querySelectorAll('.ref-project-group').forEach(g=>g.hidden=!g.textContent.toLowerCase().includes(term))});updateSidebarState();}
function updateSidebarState(){document.querySelectorAll('[data-ref-nav]').forEach(b=>{if(b.dataset.refNav===state.view){b.setAttribute('data-active','true');b.setAttribute('aria-current','page')}else{b.removeAttribute('data-active');b.removeAttribute('aria-current')}});document.querySelectorAll('[data-ref="own-chat"]').forEach(b=>{if(state.view==='chat'&&!state.session)b.setAttribute('data-active','true');else b.removeAttribute('data-active')});document.body.classList.remove('ref-nav-open')}
function capability(agent){modal('使用 '+esc(agent.name),agent.owner+' 共享的智能体',`<dl class="ref-capability"><dt>授权项目</dt><dd>${agent.id==='writer'?'Steer':'Relay'}</dd><dt>运行环境</dt><dd>${esc(agent.runtime)}</dd><dt>模型</dt><dd>${esc(agent.model)}</dd><dt>执行目录</dt><dd>独立 Git worktree</dd></dl><p class="ref-dialog-footnote">在你的工作区创建私密会话，执行机器由提供者管理。</p><footer><button type="button" class="ref-secondary" data-ref="close-dialog">取消</button><button type="button" class="ref-primary" data-ref="confirm-agent" data-agent="${agent.id}">${agent.status==='pending'?'接受并开始聊天':'开始聊天'}</button></footer>`)}
// Keep the real Sidebar DOM and add only received collaboration projects.
const sidebar=$('.ws-sidebar');sidebar.querySelectorAll('button').forEach(b=>{const label=b.textContent.trim();if(label==='协作会话'){b.dataset.ref='collaboration';b.dataset.refNav='collaboration';b.insertAdjacentHTML('afterend',`<div class="ref-sidebar-collaboration">${groupedSessions(true)}</div>`)}if(label==='智能体'){b.dataset.ref='agents';b.dataset.refNav='agents'}if(label==='登录重连与异常处理'){b.dataset.ref='own-chat';b.insertAdjacentHTML('beforeend',`<span class="ref-sidebar-shared" title="已开启协作">${icon('users')}</span>`)} });
const footer=sidebar.querySelector('.ws-sidebar-footer');footer.insertAdjacentHTML('afterbegin','<div class="ref-demo"><span>共享 UI 交互预览</span><p>本地演示，不发送邀请或执行任务。</p><button type="button" data-ref="long-title">体验长标题</button></div>');
document.addEventListener('click',e=>{const action=e.target.closest('[data-ref]');if(!action)return;const command=action.dataset.ref;
if(command==='close-dialog'){dialog.close();return}if(command==='invite'){renderInvite();return}if(command==='public-link'){modal('分享查看链接','分享当前会话的只读内容。',`<label class="ref-public-link"><input aria-label="查看链接" readonly value="https://steer.example/share?token=demo-view-only"><button type="button" class="ref-primary" data-ref="copy-link">${icon('copy')}复制</button></label><p class="ref-dialog-footnote">拿到链接的人可以查看这份内容。参与协作需另行邀请。</p>`);return}if(command==='copy-link'){void navigator.clipboard?.writeText('https://steer.example/share?token=demo-view-only').catch(()=>{});tell('查看链接已复制');return}
if(command==='remove-member'){const kind=state.dialogKind||'session',agent=state.popupAgent;(kind==='agent'?agentMembers:members).splice(Number(action.dataset.index),1);dialog.close();if(state.view==='agents')renderAgents(state.tab);else renderChat(state.session);renderInvite(kind,agent);return}if(command==='collaboration'){renderCollaboration();return}if(command==='agents'){renderAgents();return}if(command==='own-chat'){renderChat();return}if(command==='agent-tab'){renderAgents(action.dataset.tab);return}
if(command==='agent-share'){renderInvite('agent',agents.find(a=>a.id===action.dataset.agent));return}if(command==='agent-detail'){capability(provided.find(a=>a.id===action.dataset.agent));return}
if(command==='agent-use'){renderChat();tell('已准备个人新会话');return}if(command==='confirm-agent'){const a=provided.find(a=>a.id===action.dataset.agent);a.status='accepted';dialog.close();renderChat();main.querySelector('.ws-chat-appbar-context strong').textContent=a.name+' · 新会话';main.querySelector('.ws-chat-thread').innerHTML='';main.querySelector('.ws-inline-editor').focus();tell('已创建你的私密会话');return}
if(command==='open-incoming'){const s=incoming.find(s=>s.id===action.dataset.session);if(s.status==='pending'){modal('接受会话邀请',s.owner+' 的 '+s.project,`<p class="ref-dialog-message">${esc(s.title)}</p><p class="ref-dialog-footnote">${s.role==='view'?'你可以查看此会话的消息和结果。':'你可以查看消息，并使用此会话的 Agent 发起任务。'}</p><footer><button type="button" class="ref-secondary" data-ref="close-dialog">取消</button><button type="button" class="ref-primary" data-ref="accept-session" data-session="${s.id}">接受并打开</button></footer>`)}else renderChat(s);return}
if(command==='accept-session'){const s=incoming.find(s=>s.id===action.dataset.session);s.status='accepted';dialog.close();renderChat(s);return}if(command==='access'){const s=state.session;modal('会话访问权限',s.owner+' 的 '+s.project,`<dl class="ref-capability"><dt>权限</dt><dd>${s.role==='view'?'可查看':'可协作'}</dd><dt>会话</dt><dd>${esc(s.title)}</dd></dl><footer><button class="ref-secondary" data-ref="close-dialog">关闭</button></footer>`);return}
if(command==='send'){e.preventDefault();sendDemo();return}if(command==='toggle-sidebar'){document.body.classList.toggle('ref-nav-open');return}
if(command==='long-title'){renderInvite();dialog.querySelector('.ref-dialog-context').textContent='Steer · 当前项目我们增加一个 conversation task API，这样我们除了通过 web 接入，还可以通过其他终端接入，比如通过飞书机器人';return}
});
dialog.addEventListener('submit',e=>{e.preventDefault();const form=e.target.closest('.ref-invite-form');if(!form)return;const data=new FormData(form),email=String(data.get('email'));const kind=form.dataset.kind,agent=state.popupAgent,currentMembers=kind==='agent'?agentMembers:members;if(currentMembers.some(m=>m.email===email)){tell('这个成员已经在邀请列表中');return}currentMembers.push({name:email.split('@')[0],email,role:String(data.get('role')),status:'pending'});dialog.close();if(state.view==='agents')renderAgents(state.tab);else renderChat(state.session);renderInvite(kind,agent);tell('邀请已加入列表（演示）')});
dialog.addEventListener('change',e=>{if(e.target.matches('[data-member-role]')){(state.dialogKind==='agent'?agentMembers:members)[Number(e.target.dataset.memberRole)].role=e.target.value;tell('权限已更新（演示）')}});
const initial=new URLSearchParams(location.search);
if(initial.get('view')==='agents')renderAgents(initial.get('tab')==='received'?'received':'mine');
else if(initial.get('view')==='collaboration')renderCollaboration();
else renderChat();
if(initial.get('dialog')==='invite')renderInvite();
})().catch(e=>{document.body.insertAdjacentHTML('beforeend','<p role="alert">原型加载失败，请刷新页面。</p>');throw e});
